(()=>{'use strict';
const $=id=>document.getElementById(id),M=NitrogenMechanisms,c=CATALOG.find(c=>c.id==='nitrogen');
const s={step:0,pH:8.5,incorporated:false,drainage:true,anoxic:true,carbon:true,speed:1,lossMode:'volatilization',microView:false,e:null};
const world=new PlantWorld.World($('scene'),{extent:16.8,target:-.15,pitch:.29,yaw:-.23});
world.draw=w=>NitrogenWorld.draw(w,s);world.sky=()=>NitrogenWorld.sky(world,s);world.onInteract=()=>{$('rotate').setAttribute('aria-pressed','false')};
document.title='土壤中的氮素转化 · 机理与损失路径';$('title').textContent=c.title;$('stage-keyword').textContent='分清形态 · 看清过程 · 找到出口';
const panel=document.createElement('aside');panel.className='nitrogen-panel';panel.setAttribute('aria-label','本步机理说明');panel.innerHTML='<div class="n-eyebrow" id="n-kind"></div><h2 id="n-title"></h2><div class="n-formula" id="n-formula"></div><ol id="n-points"></ol><div id="n-live" class="n-live" aria-live="polite"></div><details><summary>再讲清楚一点</summary><p id="n-detail"></p></details><a class="n-source" href="https://github.com/Lidong-Huang/plant-nutrition-lab/blob/main/docs/氮素转化机理.md" target="_blank" rel="noopener">详细机理与来源 ↗</a>';document.querySelector('.stage').append(panel);
const legend=document.createElement('div');legend.className='nitrogen-legend';legend.innerHTML='<span style="--c:#d3b75d">NH₄⁺</span><span style="--c:#67aabc">NO₃⁻</span><span style="--c:#d8945a">NH₃</span><span style="--c:#a18caf">N₂O / N₂</span>';document.querySelector('.stage').append(legend);
M.steps.forEach((step,i)=>{const b=document.createElement('button');b.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span>${step.title}`;b.onclick=()=>{stop();setStep(i)};$('steps').append(b)});
let auto=false,timer=null;
function setStep(i){s.microView=false;world.focusX=0;world.target=-.15;world.extent=16.8;s.step=Math.max(0,Math.min(M.steps.length-1,i));update(true)}
function getConditions(){return M.evaluate({pH:s.pH,incorporated:s.incorporated,drainage:s.drainage,anoxic:s.step===3?false:s.anoxic,carbon:s.carbon})}
function update(buildControls=false){s.e=getConditions();const step=M.steps[s.step],loss=M.activeLoss(s.step,s.lossMode);document.querySelectorAll('#steps button').forEach((b,i)=>{b.classList.toggle('active',i===s.step);b.setAttribute('aria-current',i===s.step?'step':'false')});$('steps').children[s.step].scrollIntoView({block:'nearest',inline:'nearest'});$('n-kind').textContent=`${String(s.step+1).padStart(2,'0')} / ${step.type}`;$('n-title').textContent=step.heading;$('n-formula').textContent=step.formula;$('n-points').replaceChildren(...step.points.map(text=>{const li=document.createElement('li');li.textContent=text;return li}));$('n-detail').textContent=step.detail;$('caption').textContent=step.heading;$('description').textContent=step.heading+'。'+step.points.join('。');$('progress').textContent=`${s.step+1} / ${M.steps.length}`;$('prev').disabled=s.step===0;$('next').disabled=s.step===M.steps.length-1;
 let live='',readout='有机氮 → 铵态氮 → 硝态氮';
 if(loss==='volatilization'){const p=s.e.nh3Fraction*100,percent=p<.1?p.toFixed(3):p.toFixed(1);live=`<strong>溶液中 NH₃ 比例 <b id="nh3-percent">${percent}%</b></strong><span>占 NH₄⁺ + NH₃；25°C 近似平衡</span><p>这不是田间挥发损失率。</p><em>${s.incorporated?'当前：混入土层，示意逸散路径受阻。':'当前：表施，NH₃ 更容易到达空气。'}</em>`;readout=`NH₄⁺ ⇌ NH₃ · 施肥点 pH ${s.pH.toFixed(1)} · ${s.incorporated?'混入土层':'表施'}`}
 else if(loss==='leaching'){live=`<strong id="drainage-status">${s.drainage?'当前：有向下排水，NO₃⁻ 越过根层':'当前：先蓄水，未形成图示淋洗出口'}</strong><span>蓝色是水，内部青色粒子是 NO₃⁻。</span><p>向下迁移 ≠ 挥发成气体。</p>`;readout=s.drainage?'雨后形成向下排水 · NO₃⁻ 随水出根层':'降雨先补充蓄水 · 出口暂未形成'}
 else if(loss==='denitrification'){live=`<strong id="denitrification-status">${s.e.denitrificationActive?'当前：缺氧 + 可用有机碳，反硝化路径活跃':s.anoxic?'当前：缺少可用电子供体，路径弱化':'当前：氧较充足，反硝化路径弱化'}</strong><span>气体为 N₂O / N₂，不是 NH₃。</span><p>缺氧只是条件之一，并非所有硝态氮立即气化。</p>`;readout=`${s.anoxic?'缺氧积水':'通气有氧'} · ${s.carbon?'有可用有机碳':'缺少可用有机碳'}`}
 else if(s.step===3)readout='有氧微生物氧化 · 经 NO₂⁻ · 可释放 H⁺';
 else if(s.step===2)readout=s.incorporated?'尿素混入土层 · 脲酶参与水解':'表面尿素水解 · 施肥点 pH 可短时升高';
 else if(s.step===4)readout='吸收、吸附、微生物同化 · 三者不等同';
 $('n-live').innerHTML=live;$('n-live').hidden=!live;$('readout').textContent=readout;$('scene').dataset.step=s.step;$('scene').dataset.loss=loss||'transformation';$('scene').dataset.model=readout;$('scene').setAttribute('aria-label',`${step.title}三维演示。${step.heading}。拖动旋转、滚轮缩放。`);if(buildControls)controls();else syncButtons()}
function button(id,text,action,pressed){const b=document.createElement('button');b.id=id;b.textContent=text;b.className='n-control';if(pressed!=null)b.setAttribute('aria-pressed',String(pressed));b.onclick=()=>{stop();action();update(true)};$('controls').append(b);return b}
function controls(){if(s.microView&&!([1,2,3,4,7].includes(s.step)||(s.step===8&&s.lossMode==='denitrification'))){s.microView=false;world.focusX=0;world.target=-.15;world.extent=16.8}$('controls').replaceChildren();if(s.step===5){const label=document.createElement('label');label.htmlFor='n-ph';label.innerHTML=`<span>施肥点 pH</span><output>${s.pH.toFixed(1)}</output><input id="n-ph" type="range" min="5.5" max="9.5" step=".1" value="${s.pH}" aria-label="施肥点 pH">`;label.querySelector('input').oninput=e=>{stop();s.pH=Number(e.target.value);label.querySelector('output').textContent=s.pH.toFixed(1);update()};$('controls').append(label);button('n-placement',s.incorporated?'混入土层':'表施尿素',()=>s.incorporated=!s.incorporated,s.incorporated)}
 else if(s.step===2)button('n-placement',s.incorporated?'混入土层':'表施尿素',()=>s.incorporated=!s.incorporated,s.incorporated);
 else if(s.step===6)button('n-drainage',s.drainage?'情景：有向下排水':'情景：先补充蓄水',()=>s.drainage=!s.drainage,s.drainage);
 else if(s.step===7){button('n-oxygen',s.anoxic?'缺氧积水':'通气有氧',()=>s.anoxic=!s.anoxic,s.anoxic);button('n-carbon',s.carbon?'有可用有机碳':'缺少可用有机碳',()=>s.carbon=!s.carbon,s.carbon)}
 else if(s.step===8){for(const [mode,label] of [['volatilization','氨挥发'],['leaching','NO₃⁻ 淋洗'],['denitrification','反硝化']]){const b=button('n-'+mode,label,()=>s.lossMode=mode,s.lossMode===mode);b.dataset.loss=mode}}
 else{const label=document.createElement('label');label.htmlFor='n-speed';label.innerHTML=`<span>演示速度</span><output>${s.speed.toFixed(1)}×</output><input id="n-speed" type="range" min=".5" max="1.8" step=".1" value="${s.speed}" aria-label="演示速度">`;label.querySelector('input').oninput=e=>{s.speed=Number(e.target.value);world.motionSpeed=s.speed;label.querySelector('output').textContent=s.speed.toFixed(1)+'×'};$('controls').append(label)}if([1,2,3,4,7].includes(s.step)||(s.step===8&&s.lossMode==='denitrification'))button('n-microview',s.microView?'返回土壤全景':'放大微生物',()=>{s.microView=!s.microView;world.focusX=s.microView?-.9:0;world.target=s.microView?-1.05:-.15;world.extent=s.microView?9.5:16.8;world.camera.yaw=-.15;world.camera.pitch=.24},s.microView)}
function syncButtons(){const micro=$('n-microview');if(micro){micro.textContent=s.microView?'返回土壤全景':'放大微生物';micro.setAttribute('aria-pressed',String(s.microView))}const p=$('n-placement');if(p){p.textContent=s.incorporated?'混入土层':'表施尿素';p.setAttribute('aria-pressed',String(s.incorporated))}const d=$('n-drainage');if(d){d.textContent=s.drainage?'情景：有向下排水':'情景：先补充蓄水';d.setAttribute('aria-pressed',String(s.drainage))}const o=$('n-oxygen');if(o){o.textContent=s.anoxic?'缺氧积水':'通气有氧';o.setAttribute('aria-pressed',String(s.anoxic))}const carbon=$('n-carbon');if(carbon){carbon.textContent=s.carbon?'有可用有机碳':'缺少可用有机碳';carbon.setAttribute('aria-pressed',String(s.carbon))}document.querySelectorAll('#controls [data-loss]').forEach(b=>{b.classList.toggle('active',b.dataset.loss===s.lossMode);b.setAttribute('aria-pressed',String(b.dataset.loss===s.lossMode))})}
function stop(){auto=false;clearInterval(timer);timer=null;$('play').textContent='▶';$('play').setAttribute('aria-pressed','false');$('play').setAttribute('aria-label','自动演示')}
function play(){if(auto){stop();return}auto=true;if(s.step===M.steps.length-1)setStep(0);world.paused=false;syncMotion();$('play').textContent='Ⅱ';$('play').setAttribute('aria-pressed','true');$('play').setAttribute('aria-label','暂停自动演示');timer=setInterval(()=>{if(s.step===M.steps.length-1){stop();return}setStep(s.step+1)},11000)}
function syncMotion(){$('motion').textContent=world.paused?'▶ 动画':'Ⅱ 动画';$('motion').setAttribute('aria-pressed',String(!world.paused))}
$('play').onclick=play;$('prev').onclick=()=>{stop();setStep(s.step-1)};$('next').onclick=()=>{stop();setStep(s.step+1)};$('motion').onclick=()=>{world.paused=!world.paused;syncMotion();if(world.paused)stop()};$('rotate').onclick=()=>{world.autoRotate=!world.autoRotate;$('rotate').setAttribute('aria-pressed',String(world.autoRotate))};$('front').onclick=()=>{world.autoRotate=false;world.camera.yaw=0;world.camera.pitch=.12;world.camera.zoom=1;$('rotate').setAttribute('aria-pressed','false')};$('tilt').onclick=()=>{world.autoRotate=false;world.camera.pitch=world.camera.pitch>.9?world.initial.pitch:1.18;$('rotate').setAttribute('aria-pressed','false')};$('reset').onclick=()=>{stop();world.resetView();world.paused=false;Object.assign(s,{pH:8.5,incorporated:false,drainage:true,anoxic:true,carbon:true,speed:1,lossMode:'volatilization'});world.motionSpeed=1;setStep(0);syncMotion();$('rotate').setAttribute('aria-pressed','false')};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('fullscreen').textContent='F11 全屏'}};
document.addEventListener('keydown',e=>{if(['INPUT','BUTTON','A','CANVAS','SUMMARY'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight'){stop();setStep(s.step+1);e.preventDefault()}else if(e.key==='ArrowLeft'){stop();setStep(s.step-1);e.preventDefault()}else if(e.code==='Space'){play();e.preventDefault()}});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
window.lessonDiagnostics={get state(){return JSON.parse(JSON.stringify(s))},get camera(){return {...world.camera}},get primitives(){return world.items.length},get time(){return world.time},get paused(){return world.paused}};setStep(0);syncMotion();
})();

